impl DeclareArgs {
    pub fn from_json(v: &crate::kernel::Json) -> Result<Self, crate::kernel::Refusal> {
        if !matches!(v, crate::kernel::Json::Object(_)) {
            return Err(crate::kernel::Refusal::TypeMismatch(format!(
                "DeclareArgs expects an object, got {}",
                v.inspect()
            )));
        }
        let unknown = v.unknown_keys(&[
            "aggregate",
            "owner",
            "name",
            "description",
            "position",
            "id",
        ]);
        if !unknown.is_empty() {
            let unknown: Vec<&str> = unknown.iter().map(String::as_str).collect();
            return Err(crate::kernel::Refusal::UnknownArgument(
                crate::kernel::refusal_wording::UnknownArgumentUnknownArgsArgs {
                    command: "Declare",
                    unknown: &unknown,
                    declared: &["aggregate", "owner", "name", "description", "position"],
                }
                .render_args(),
            ));
        }
        let required: &[&str] = &["aggregate", "name", "owner"];
        let absent: Vec<&str> = required
            .iter()
            .copied()
            .filter(|key| v.get(key).is_none())
            .collect();
        if !absent.is_empty() {
            return Err(crate::kernel::Refusal::AbsentArgument(
                crate::kernel::refusal_wording::AbsentArgumentAbsentArgsArgs {
                    command: "Declare",
                    absent: &absent,
                    declared: &["aggregate", "owner", "name", "description", "position"],
                }
                .render_args(),
            ));
        }
        let aggregate = {
            let x = v.get("aggregate").ok_or_else(|| {
                crate::kernel::Refusal::TypeMismatch(
                    "Entity.aggregate expects String, got nil".to_string(),
                )
            })?;
            x.as_str().map(ToString::to_string).ok_or_else(|| {
                crate::kernel::Refusal::TypeMismatch(format!(
                    "Entity.aggregate expects String, got {}",
                    x.describe()
                ))
            })?
        };
        let owner = EntityText::from_json(
            &(match v.get("owner").ok_or_else(|| {
                crate::kernel::Refusal::TypeMismatch(
                    "Declare.owner expects EntityText, got nil".to_string(),
                )
            })? {
                crate::kernel::Json::Null => crate::kernel::Json::Object(Vec::new()),
                other => other.clone(),
            })
            .coerce_single_field("value"),
        )?;
        owner.check_invariants()?;
        let name = EntityName::from_json(
            &(match v.get("name").ok_or_else(|| {
                crate::kernel::Refusal::TypeMismatch(
                    "Declare.name expects EntityName, got nil".to_string(),
                )
            })? {
                crate::kernel::Json::Null => crate::kernel::Json::Object(Vec::new()),
                other => other.clone(),
            })
            .coerce_single_field("value"),
        )?;
        name.check_invariants()?;
        let description = match v.get("description") {
            Some(crate::kernel::Json::Null) | None => None,
            Some(x) => Some(EntityName::from_json(&x.coerce_single_field("value"))?),
        };
        if let Some(v) = &description {
            v.check_invariants()?;
        }
        let position = match v.get("position") {
            Some(crate::kernel::Json::Null) | None => None,
            Some(x) => Some(Position::from_json(&x.coerce_single_field("value"))?),
        };
        if let Some(v) = &position {
            v.check_invariants()?;
        }
        Ok(Self {
            aggregate,
            owner,
            name,
            description,
            position,
        })
    }
}

